#include <stdio.h>

int main() {
    FILE *fp;

    // 1. Write Mode ("w")
    // Creates data.txt (Overwrites if exists)
    fp = fopen("data.txt", "w");
    if (fp) {
        fprintf(fp, "Hello File!");
        fclose(fp);
    }

    // 2. Append Mode ("a")
    // Adds to the end
    fp = fopen("data.txt", "a");
    if (fp) {
        fprintf(fp, " Append me.");
        fclose(fp);
    }

    // 3. Read Mode ("r")
    fp = fopen("data.txt", "r");
    char buffer[50];
    if (fp) {
        fgets(buffer, 50, fp);
        printf("Read: %s\n", buffer);
        fclose(fp);
    }

    return 0;
}
